INSERT INTO `products` VALUES (1,'White stone kodi attigai','B0001','white-stone-kodi-attigai','Imbued with sacred South Indian heritage, the White stone kodi attigai is masterfully fashioned in sacred five-metal Panchalogam (Impon) alloy. Each curve and motif reflects century-old temple jewelry artistry, accented by rich 24K micro gold electroplating that bestows an authentic 22K bridal radiance. Engineered with an anti-tarnish protective lacquer for long-lasting brilliance, it pairs seamlessly with Kanjeevaram silks, festive drapes, and ceremonial attire. Hypoallergenic, comfortable for all-day celebrations, and presented in signature luxury gift-ready packaging.','prod-b0001-main.jpg',999.00,899.00,846.61,18,152.39,999.00,'include',1,10,5,0,NULL,1,'2026-09-21 06:43:36','2026-09-21 09:29:23',NULL,NULL,4),(2,'2 layer white royal attigai','B0002','2-layer-white-royal-attigai','Imbued with sacred South Indian heritage, the 2 layer white royal attigai is masterfully fashioned in sacred five-metal Panchalogam (Impon) alloy. Each curve and motif reflects century-old temple jewelry artistry, accented by rich 24K micro gold electroplating that bestows an authentic 22K bridal radiance. Engineered with an anti-tarnish protective lacquer for long-lasting brilliance, it pairs seamlessly with Kanjeevaram silks, festive drapes, and ceremonial attire. Hypoallergenic, comfortable for all-day celebrations, and presented in signature luxury gift-ready packaging.','prod-b0002-main.jpg',1499.00,1299.00,1270.34,18,228.66,1499.00,'include',1,5,5,0,NULL,1,'2026-09-21 06:43:36','2026-09-21 09:29:23',NULL,NULL,2),(3,'premium white stone attigai','B0003','premium-white-stone-attigai','Imbued with sacred South Indian heritage, the premium white stone attigai is masterfully fashioned in sacred five-metal Panchalogam (Impon) alloy. Each curve and motif reflects century-old temple jewelry artistry, accented by rich 24K micro gold electroplating that bestows an authentic 22K bridal radiance. En