DROP TABLE IF EXISTS `productvariants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `productvariants` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `productId` int(11) NOT NULL,
  `groupId` int(11) DEFAULT NULL,
  `variantType` varchar(100) DEFAULT NULL,
  `variantValue` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `video` varchar(255) DEFAULT NULL,
  `stock` int(11) DEFAULT 0,
  `salesStock` int(11) DEFAULT 0,
  `mrpPrice` decimal(10,2) DEFAULT NULL,
  `salesPrice` decimal(10,2) DEFAULT NULL,
  `mainImage` varchar(255) DEFAULT NULL,
  `thumbnails` text DEFAULT NULL,
  `specifications` text DEFAULT NULL,
  `subOptions` text DEFAULT NULL,
  `status` tinyint(1) DEFAULT 1,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `productId` (`productId`),
  CONSTRAINT `productvariants_ibfk_1` FOREIGN KEY (`productId`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
