INSERT INTO `settings` VALUES ('ABOUT_PAGE_DATA','{\"aboutEyebrow\":\"ABOUT BAANI JEWELS\",\"heroTitle\":\"Welcome to Baani Jewels\",\"heroSubtitle\":\"Luxury Made Affordable\",\"leadPara\":\"Baani Jewels brings elegant, trendy and premium-looking jewellery to customers who believe that style should never come with an extravagant price tag.\",\"bodyPara1\":\"We are excited to bring Baani Jewels to you through our very own website, making it easier to discover and shop for beautiful jewellery wherever you are in the world.\",\"bodyPara2\":\"From everyday elegance to special occasions, celebrations and bridal moments, we offer carefully selected designs that add a touch of beauty and sophistication to every look.\",\"heroImage\":\"/assests/about_2nd_banner.jpeg\",\"badgeNumber\":\"100%\",\"badgeLabel\":\"Luxury Made Affordable\",\"philosophyTag\":\"OUR PHILOSOPHY\",\"philosophyTitle\":\"What We Believe\",\"philosophyQuote\":\"At Baani Jewels, we believe that everyone deserves to feel beautiful, confident and special without having to compromise on style or affordability.\",\"philosophySignature\":\"— Baani Jewels Atelier\",\"whyEyebrow\":\"DISTINCTIVE CRAFTSMANSHIP\",\"whyTitle\":\"Why Baani Jewels?\",\"whySubtitle\":\"Designed for brilliance, created for comfort, priced for everyone.\",\"whyCards\":[{\"title\":\"Trendy & Elegant Designs\",\"description\":\"Contemporary, runway-inspired jewelry curated to match your modern grace and timeless elegance.\"},{\"title\":\"Premium-Looking Jewellery\",\"description\":\"Impeccable craftsmanship and lustrous finishing that rival high-end luxury heirlooms.\"},{\"title\":\"Luxury at Affordable Prices\",\"description\":\"High jewelry aesthetics thoughtfully crafted without extravagant price tags.\"},{\"title\":\"Carefully Selected Collections\",\"description\":\"Each design is hand-selected with discernment for everyday elegance, parties, and bridal moments.\"},{\"title\":\"Delivery Across the World\",\"description\":\"Fast, secure and worldwide shipping bringing Baani Jewels straight to your doorstep wherever you are.\"},{\"title\":\"Easy & Convenient Online Shopping\",\"description\":\"Seamless online experience with hassle-free ordering, dedicated customer care, and safe payments.\"}],\"journeyEyebrow\":\"OUR JOURNEY\",\"journeyHeading\":\"Built on Love & Trust\",\"journeyBody\":\"Our journey has been built on the love and trust of our customers, and we look forward to growing together and reaching jewellery lovers across the world.\",\"journeyImage\":\"/assests/about_model.png\",\"journeyHighlight\":\"Baani Jewels – Luxury Made Affordable\",\"galleryEyebrow\":\"The Collection\",\"galleryTitle\":\"A closer look at our artistry.\",\"ctaEyebrow\":\"Come, Explore\",\"ctaTitle\":\"Find the piece that finds you.\",\"ctaText\":\"Visit our collection and discover jewelry crafted to make you shine on every occasion.\",\"ctaButtonText\":\"Explore Collection\"}','2026-09-17 07:55:39','2026-09-20 09:29:15'),('COMPANY_STATE','Tamil Nadu','2026-09-03 06:25:00','2026-09-03 06:25:00'),('CONTACT_PAGE_DATA','{\"feedbackEyebrow\":\"THOUGHTS\",\"feedbackTitle\":\"We Value Feedback\",\"feedbackDesc\":\"We\'d love to hear from you. Whether you have a question about our collections, need assistance with your order, or just want to share your thoughts, our concierge team is ready to help.\",\"feedbackImg1\":\"/assests/pr4.jpeg\",\"feedbackImg2\":\"/assests/pr7.jpeg\",\"feedbackImg3\":\"/assests/pr10.jpeg\",\"touchEyebrow\":\"GET IN TOUCH\",\"touchTitle\":\"Branching Out For You\",\"phone\":\"+91 93453 22621\",\"phone2\":\"+91 81899 44905\",\"whatsapp\":\"919345322621\",\"email\":\"Baanijewels.ind@gmail.com\",\"sms\":\"+919345322621\",\"locationText\":\"Proudly Based in Chennai, TN\",\"addressLine1\":\"Baani Jewels Atelier\",\"addressLine2\":\"Chennai, Tamil Nadu, India\",\"businessHours\":\"Mon – Sat: 9:00 AM – 7:00 PM\",\"mapIframe\":\"https://maps.google.com/maps?q=Chennai,%20TN&t=&z=13&ie=UTF8&iwloc=&output=embed\"}','2026-09-17 07:55:39','2026-09-20 09:29:39'),('DEFAULT_SHIPPING_FEE','150','2026-09-03 06:25:00','2026-09-03 06:25:00'),('FREE_SHIPPING_COD_ACTIVE','false','2026-09-17 06:18:24','2026-09-17 06:18:24'),('FREE_SHIPPING_COD_THRESHOLD','0','2026-09-17 06:18:24','2026-09-17 06:18:24'),('FREE_SHIPPING_ONLINE_ACTIVE','false','2026-09-17 06:18:24','2026-09-20 09:35:30'),('FREE_SHIPPING_ONLINE_THRESHOLD','300','2026-09-17 06:18:24','2026-09-17 06:18:24'),('FREE_SHIPPING_THRESHOLD','1000','2026-09-03 06:25:00','2026-09-03 06:25:00');
