INSERT INTO `testimonials` VALUES (1,'Dr. Radhika Menon','Chennai',5,'The craftsmanship of the royal haaram set took my breath away. It has the authentic feel and weight of heritage heirloom jewellery. Everyone at the reception was asking where I got it from!',NULL,1,'2026-09-16 06:21:53','2026-09-16 06:21:53'),(2,'Kavitha Sundaram','Coimbatore',5,'Exceptional finish and premium matte antique polish! I ordered the temple choker and matching jhumkas. The packaging was stunning, and delivery was prompt. Baani Jewels is now my go-to brand.',NULL,1,'2026-09-16 06:21:53','2026-09-16 06:21:53'),(3,'Ananya Deshmukh','Bangalore',5,'Truly royal artistry. The intricate ruby detailing and skin-safe brass coating make it so comfortable to wear all evening. Outstanding service and 5-star quality!',NULL,1,'2026-09-16 06:21:53','2026-09-16 06:21:53');
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
UNLOCK TABLES;

